using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capability to the research agent.
/// Uses a configurable search API (defaults to DuckDuckGo Instant Answer API).
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;
    private readonly ILogger<WebSearchTool> _logger;

    public WebSearchTool(HttpClient httpClient, ILogger<WebSearchTool> logger)
    {
        _httpClient = httpClient;
        _logger = logger;
    }

    [Description("Searches the web for information on a given query. Returns a list of relevant results with titles, URLs, and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        [Description("Maximum number of results to return (default: 5)")] int maxResults = 5)
    {
        _logger.LogInformation("Searching web for: {Query}", query);

        try
        {
            // Use DuckDuckGo Instant Answer API (no API key required)
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

            var response = await _httpClient.GetAsync(url);
            response.EnsureSuccessStatusCode();

            var json = await response.Content.ReadFromJsonAsync<JsonElement>();
            var results = new List<SearchResult>();

            // Extract abstract if available
            var abstractText = json.GetProperty("Abstract").GetString();
            var abstractSource = json.GetProperty("AbstractSource").GetString();
            var abstractUrl = json.GetProperty("AbstractURL").GetString();

            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                results.Add(new SearchResult(
                    Title: abstractSource ?? "Summary",
                    Url: abstractUrl ?? "",
                    Snippet: abstractText));
            }

            // Extract related topics
            if (json.TryGetProperty("RelatedTopics", out var relatedTopics))
            {
                foreach (var topic in relatedTopics.EnumerateArray())
                {
                    if (results.Count >= maxResults) break;

                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;

                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        results.Add(new SearchResult(
                            Title: text.Length > 80 ? text[..80] + "..." : text,
                            Url: firstUrl ?? "",
                            Snippet: text));
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No results found for '{query}'. Try rephrasing the search query.";
            }

            var output = $"Search results for '{query}':\n\n";
            for (int i = 0; i < results.Count; i++)
            {
                output += $"{i + 1}. **{results[i].Title}**\n";
                output += $"   URL: {results[i].Url}\n";
                output += $"   {results[i].Snippet}\n\n";
            }

            _logger.LogInformation("Found {Count} results for: {Query}", results.Count, query);
            return output;
        }
        catch (HttpRequestException ex)
        {
            _logger.LogWarning(ex, "Web search failed for query: {Query}", query);
            return $"Search failed: {ex.Message}. Please try again with a different query.";
        }
    }

    private sealed record SearchResult(string Title, string Url, string Snippet);
}

using System.ComponentModel;
using Microsoft.Extensions.Logging;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capability for the research agent to organize findings.
/// Notes are stored in-memory and can be retrieved for final summarization.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<ResearchNote> _notes = [];
    private readonly ILogger<NoteTakingTool> _logger;

    public NoteTakingTool(ILogger<NoteTakingTool> logger)
    {
        _logger = logger;
    }

    [Description("Saves a research note with a topic label and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short label categorizing this note (e.g., 'definition', 'key finding', 'statistic')")] string topic,
        [Description("The content of the note — a fact, insight, or piece of information discovered during research")] string content,
        [Description("The source URL or reference where this information was found")] string source = "")
    {
        var note = new ResearchNote(topic, content, source, DateTime.UtcNow);
        _notes.Add(note);

        _logger.LogInformation("Note saved — Topic: {Topic}, Notes count: {Count}", topic, _notes.Count);
        return $"Note saved successfully. You now have {_notes.Count} note(s) recorded.";
    }

    [Description("Retrieves all saved research notes organized by topic. Use this before writing a final summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet. Use SearchWeb to find information, then SaveNote to record findings.";
        }

        var grouped = _notes.GroupBy(n => n.Topic, StringComparer.OrdinalIgnoreCase);
        var output = $"=== Research Notes ({_notes.Count} total) ===\n\n";

        foreach (var group in grouped)
        {
            output += $"## {group.Key}\n";
            foreach (var note in group)
            {
                output += $"- {note.Content}";
                if (!string.IsNullOrWhiteSpace(note.Source))
                {
                    output += $" [Source: {note.Source}]";
                }
                output += "\n";
            }
            output += "\n";
        }

        return output;
    }

    [Description("Returns the count of notes saved so far.")]
    public string GetNoteCount()
    {
        return $"You have {_notes.Count} note(s) saved.";
    }

    public IReadOnlyList<ResearchNote> Notes => _notes.AsReadOnly();

    public sealed record ResearchNote(string Topic, string Content, string Source, DateTime Timestamp);
}

