using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;
using OpenAI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddHttpClient<WebSearchTool>();
builder.Services.AddSingleton<NoteTakingTool>();

// Register the chat client via MEAI abstraction with OpenAI provider
var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(services =>
{
    var apiKey = builder.Configuration["AI:ApiKey"]
        ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
        ?? throw new InvalidOperationException(
            "Set the OPENAI_API_KEY environment variable or configure AI:ApiKey.");

    var openAiClient = new OpenAIClient(apiKey);
    IChatClient innerClient = openAiClient.GetChatClient(modelId).AsIChatClient();

    return new ChatClientBuilder(innerClient)
        .UseLogging()
        .UseFunctionInvocation()
        .Build(services);
});

var host = builder.Build();

var logger = host.Services.GetRequiredService<ILoggerFactory>().CreateLogger("ResearchAgent");
var chatClient = host.Services.GetRequiredService<IChatClient>();
var webSearchTool = host.Services.GetRequiredService<WebSearchTool>();
var noteTakingTool = host.Services.GetRequiredService<NoteTakingTool>();

// Build the agent with tools
var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes before providing a comprehensive summary.",
    instructions: """
        You are a research assistant. When given a topic to research:
        1. Search the web multiple times with different queries to gather diverse information.
        2. Save important findings as notes using the note-taking tool, categorizing them by topic.
        3. After gathering sufficient information, retrieve all your notes.
        4. Provide a well-structured summary of your findings with key points and sources.

        Be thorough but concise. Always cite sources when available.
        """,
    tools:
    [
        AIFunctionFactory.Create(webSearchTool.SearchWebAsync),
        AIFunctionFactory.Create(noteTakingTool.SaveNote),
        AIFunctionFactory.Create(noteTakingTool.GetAllNotes),
        AIFunctionFactory.Create(noteTakingTool.GetNoteCount),
    ]);

// Get the research topic
var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");
Console.WriteLine(new string('─', 60));

// Run the agent
var session = await agent.CreateSessionAsync();
var runOptions = new ChatClientAgentRunOptions
{
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

try
{
    var response = await agent.RunAsync(
        $"Research the following topic and provide a comprehensive summary: {topic}",
        session,
        runOptions);

    Console.WriteLine("\n📋 Research Summary:\n");
    Console.WriteLine(new string('─', 60));

    foreach (var message in response.Messages)
    {
        if (message.Role == ChatRole.Assistant && message.Text is { Length: > 0 })
        {
            Console.WriteLine(message.Text);
        }
    }

    // Display collected notes
    if (noteTakingTool.Notes.Count > 0)
    {
        Console.WriteLine($"\n\n📝 Notes collected: {noteTakingTool.Notes.Count}");
        Console.WriteLine(new string('─', 60));
        foreach (var note in noteTakingTool.Notes)
        {
            Console.WriteLine($"  [{note.Topic}] {note.Content}");
        }
    }
}
catch (Exception ex)
{
    logger.LogError(ex, "Research agent failed");
    Console.WriteLine($"\n❌ Error: {ex.Message}");
    Console.WriteLine("Ensure the OPENAI_API_KEY environment variable is set.");
    return 1;
}

return 0;

static string PromptForTopic()
{
    Console.Write("Enter a topic to research: ");
    var input = Console.ReadLine()?.Trim();
    if (string.IsNullOrWhiteSpace(input))
    {
        Console.WriteLine("No topic provided. Using default: 'quantum computing'");
        return "quantum computing";
    }
    return input;
}

